_BA = ActionCost.BONUS_ACTION
_SWARM_RES = "bludgeoning, piercing, slashing"
_SWARM_CIMM = "charmed, frightened, grappled, paralyzed, petrified, prone, restrained, stunned"


def _prone(dc: int):
    return dict(on_hit_save=sv(A.STR, dc), on_hit_conditions=(cond("prone", -1),))


def _poison_para(dc: int, dmg: str):
    """Spider-style poison bite rider: CON save for half; at 0 hp target is stable, poisoned and paralyzed."""
    return dict(on_hit_save=sv(A.CON, dc, half=True), on_hit_save_damage=dm(dmg),
                on_hit_effect=eff("poison_paralysis_at_zero", 600, always=True))


def _charge(name: str, dice: str, dtype: str, dc: int, min_ft: int = 20) -> dict:
    return {"charge": {"min_move_ft": min_ft, "damage": f"{dice} {dtype}", "save": "str", "dc": dc, "effect": "prone"}}


